from shapely.geometry import LineString, mapping
import json
from shapely import set_precision
line = LineString([(390000,5820000),(390400,5820300),(390800,5820100)])
poly = line.buffer(25, quad_segs=16, cap_style='round', join_style='round')
def r(c): return [round(x,5) for x in c]
def rr(g):
    if g.geom_type=='Polygon':
        return {"type":"Polygon","coordinates":[[r(p) for p in ring] for ring in [list(g.exterior.coords)]]}
print(json.dumps(rr(poly), separators=(',',':')))

